import * as React from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";

/*
  Settings page archetype — the fourth of the source app's five page shapes, and
  the one the DS has no composed pattern for yet.

  Anatomy: a left section nav (Tier-3, inside the content layer — it is NOT the
  Tier-2 sidebar, which this workspace does not have) + one section panel at a
  time. Sections switch rather than scroll: with a handful of short sections a
  scroll-spy costs more than it returns, and switching keeps the save footer
  bound to exactly the fields on screen.

  DS FOLLOW-UP: nothing here is Profile- or Settings-specific. If a second app
  needs a settings page, this belongs beside `form-layout/` in the DS as
  `SettingsLayout`, with the section list as its only required prop.
*/

export interface SettingsSection {
  key: string;
  label: string;
  icon?: React.ReactNode;
  /** Section heading shown above the panel. Defaults to `label`. */
  title?: string;
  /** One line under the heading saying what the section governs. */
  description?: string;
  content: React.ReactNode;
}

export interface SettingsPageProps {
  sections: SettingsSection[];
  /** Enables the save footer. Left out, the page is read-only. */
  onSave?: () => void;
  /** Save is live only when something changed. */
  dirty?: boolean;
  onDiscard?: () => void;
}

export function SettingsPage({
  sections,
  onSave,
  dirty = false,
  onDiscard,
}: SettingsPageProps) {
  const [activeKey, setActiveKey] = React.useState(sections[0]?.key ?? "");
  const active =
    sections.find((s) => s.key === activeKey) ?? sections[0] ?? null;
  if (!active) return null;

  return (
    <div className="flex min-h-0 flex-1 gap-6">
      {/* Section nav — 200px, its own scroll, no surface of its own: the
          content layer is already a panel and a second fill would stack.
          Suppressed at one section: a nav with a single destination is chrome
          that decides nothing. */}
      {sections.length > 1 && (
      <nav
        aria-label="Settings sections"
        className="flex w-50 shrink-0 flex-col gap-1 overflow-y-auto"
      >
        {sections.map((s) => {
          const on = s.key === active.key;
          return (
            <button
              key={s.key}
              type="button"
              aria-current={on ? "page" : undefined}
              onClick={() => setActiveKey(s.key)}
              className={cn(
                "flex h-9 items-center gap-2.5 rounded-md px-3 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50 [&_svg]:size-4",
                on
                  ? "bg-accent text-foreground"
                  : "text-muted-foreground hover:bg-accent/50 hover:text-foreground"
              )}
            >
              {s.icon}
              <span className="truncate">{s.label}</span>
            </button>
          );
        })}
      </nav>
      )}

      {/* Panel — one section. Capped at 640px so form rows stay readable on a
          full-width content layer; the cap is the DS's narrow-sheet width plus
          its two 40px gutters, not a new number. */}
      <div className="flex min-h-0 min-w-0 flex-1 flex-col">
        <div className="min-h-0 flex-1 overflow-y-auto">
          <div className="flex max-w-160 flex-col gap-6 pb-2">
            <div className="flex flex-col gap-1">
              <h2 className="text-base font-semibold text-foreground">
                {active.title ?? active.label}
              </h2>
              {active.description && (
                <p className="text-sm text-muted-foreground">
                  {active.description}
                </p>
              )}
            </div>
            {active.content}
          </div>
        </div>

        {/* The footer belongs to the form column, so its rule stops where the
            fields do — a full-width rule under a 640px column read as a page
            divider with the buttons floating in the middle of it. */}
        {onSave && (
          <div className="max-w-160 shrink-0 pt-4">
            <Separator className="mb-4" />
            <div className="flex items-center justify-end gap-3">
              {onDiscard && (
                <Button variant="outline" disabled={!dirty} onClick={onDiscard}>
                  Discard
                </Button>
              )}
              <Button disabled={!dirty} onClick={onSave}>
                Save changes
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import * as React from "react";
import { CircleDot, Plus, UserRound, CalendarClock, Ban } from "lucide-react";
import { TERM_ICONS } from "@/components/ui/term-icons";
import { cn } from "@/lib/utils";
import { SheetSection } from "@/components/side-sheet/parts";
import { DATE_FMT } from "./data";

/**
 * THE CHANGE LOG, for modules that did not have one — Sales today (Pavan,
 * 2026-09-23). The same shape as a 3PL order's `audit` and a service order's:
 * one entry per save that changed something MEANINGFUL, each change in words
 * with the old value and the new.
 *
 * WHAT COUNTS IS THE MODULE'S DIFF, NOT THIS FILE. Each module passes the
 * function that decides which changes are events (the approved list); typing
 * that changes nothing on that list writes nothing.
 */
export interface ActivityEntry {
  at: string;
  by: string;
  changes: string[];
}

type Logged = { id: string; audit?: ActivityEntry[] };

/** Who is making the change. The prototype has one signed-in dispatcher. */
export const ACTOR = "Dana Whitfield";

/**
 * A row list whose setter writes the log. ONE WRAPPER ROUND THE ONLY SETTER,
 * so no path that edits a row — the sheet, a bulk edit, creation — can forget
 * to log: a new row starts with `createdText`, and a changed row gets an entry
 * listing whatever `diff` says changed.
 */
export function useLoggedRows<T extends Logged>(
  initial: T[],
  diff: (before: T, after: T) => string[],
  createdText = "Order created"
): [T[], (fn: (prev: T[]) => T[]) => void] {
  const [rows, setRaw] = React.useState<T[]>(initial);
  const setRows = React.useCallback(
    (fn: (prev: T[]) => T[]) =>
      setRaw((prev) => {
        const next = fn(prev);
        const at = new Date().toISOString();
        return next.map((r) => {
          const before = prev.find((x) => x.id === r.id);
          if (!before)
            return r.audit?.length
              ? r
              : { ...r, audit: [{ at, by: ACTOR, changes: [createdText] }] };
          if (before === r) return r;
          const changes = diff(before, r);
          return changes.length > 0
            ? { ...r, audit: [...(r.audit ?? []), { at, by: ACTOR, changes }] }
            : r;
        });
      }),
    [diff, createdText]
  );
  return [rows, setRows];
}

const STAMP_TIME = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" });
/* IN A CHOSEN ZONE WHEN ONE IS GIVEN — Sales passes its Preferences time
   zone (2026-10-07); without one, the browser's. */
const stamp = (iso: string, timeZone?: string) => {
  const d = new Date(iso);
  if (!timeZone) return `${DATE_FMT.format(d)} · ${STAMP_TIME.format(d)}`;
  const date = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric", timeZone });
  const time = new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit", timeZone });
  return `${date.format(d)} · ${time.format(d)}`;
};

function mark(text: string): { icon: React.ReactNode; tone: string } {
  const quiet = "border-border bg-card text-muted-foreground";
  if (/created/i.test(text))
    return { icon: <Plus />, tone: "border-status-success/30 bg-status-success/10 text-status-success" };
  if (/cancel/i.test(text))
    return { icon: <Ban />, tone: "border-status-failed/30 bg-status-failed/10 text-status-failed" };
  if (/^(Driver|Status)/.test(text)) return { icon: <UserRound />, tone: quiet };
  if (/^(Planned|Delivery date)/.test(text)) return { icon: <CalendarClock />, tone: quiet };
  /* THE TERM'S OWN ICON (DS term-icons, Pavan, 2026-10-20). */
  if (/^Products/.test(text)) return { icon: <TERM_ICONS.products />, tone: quiet };
  return { icon: <CircleDot />, tone: quiet };
}

/**
 * The log as a timeline — 3PL's shape: a line down the marks, most recent
 * first, the change leading and who/when under it. Rendered as its own
 * section at the foot of a sheet that has no rail.
 */
export function ActivitySection({
  entries,
  timeZone,
}: {
  entries: ActivityEntry[] | undefined;
  timeZone?: string;
}) {
  const rows = [...(entries ?? [])]
    .reverse()
    .flatMap((e, i) => e.changes.map((c, j) => ({ e, c, key: `${e.at}-${i}-${j}` })));
  return (
    <SheetSection title="Activity">
      {rows.length === 0 ? (
        <p className="text-sm text-muted-foreground">Nothing has changed yet.</p>
      ) : (
        <ol className="flex flex-col">
          {rows.map(({ e, c, key }, idx) => {
            const m = mark(c);
            return (
              <li key={key} className="relative flex gap-3 pb-4 last:pb-0">
                {idx < rows.length - 1 && (
                  <span aria-hidden className="absolute top-7 bottom-0 left-[13px] w-px bg-border" />
                )}
                <span
                  className={cn(
                    "relative z-10 flex size-7 shrink-0 items-center justify-center rounded-full border [&_svg]:size-3.5",
                    m.tone
                  )}
                >
                  {m.icon}
                </span>
                <span className="flex min-w-0 flex-col gap-0.5 pt-0.5">
                  <span className="text-sm break-words text-foreground">{c}</span>
                  <span className="text-xs text-muted-foreground">
                    {stamp(e.at, timeZone)} · {e.by}
                  </span>
                </span>
              </li>
            );
          })}
        </ol>
      )}
    </SheetSection>
  );
}

import { DATE_FMT, dateKeyOf, relativeLabel, startOfDay } from "./data";
import type { TwoLine } from "./types";
import { statusTones } from "./statusKind";
import type { ActivityEntry } from "./activity";

/*
  Asset Orders — the second rail destination.

  Columns are the five that were specified: Order #, Customer, Sales Rep,
  Delivery Date, Status. Everything structural is borrowed from Fuel Orders on
  purpose — same column-frame widths, same sort cycle, same date derivation off
  today — so the two lists read as one family rather than two designs.

  INVENTED, and flagged because it is not transcribed from the source app:
    • which stage each sample order sits at, and the Dispatched ones especially.
      The five stages themselves are Lovable's, adopted for every Sales order
      (Pavan, 2026-10-07) — see `AssetOrderStatus`.
    • the ship-tos. Each is a `SHIP_TO_SITES` name so the map can place it.
    • the sales-rep names.
    • the order numbers, which continue a separate 61xxxxx series so they cannot
      be confused with fuel order numbers.
  Customer names ARE reused from the Fuel Orders dataset, so the same accounts
  appear across both lists.
*/

/* THE SALES STAGES (Pavan, 2026-10-07) — Lovable's five, the same set Fuel
   Orders uses. Open was invented; it is Requested now. */
export type AssetOrderStatus =
  | "Requested"
  | "Scheduled"
  | "Dispatched"
  | "Delivered"
  | "Canceled"
  /* …or a stage added in Sales Settings (Pavan, 2026-10-07). */
  | (string & {});

/** Status → badge colour, by kind (`statusKind.ts`). One map; the sheet and the
 *  table both read it. */
export const ASSET_ORDER_STATUS_TONE = statusTones<CoreAssetStage>({
  /* Waiting on somebody to schedule it. */
  Requested: "caution",
  /* A date is set. True, and asks nothing. */
  Scheduled: "info",
  /* On the road. Under way, asks nothing. */
  Dispatched: "info",
  Delivered: "success",
  /* NOT RED — a terminal non-event, not a problem to solve. */
  Canceled: "neutral",
});

type CoreAssetStage = "Requested" | "Scheduled" | "Dispatched" | "Delivered" | "Canceled";

/** In stage order — the filter, the group-by and the sort all read it. */
