/**
 * Kanban board, generic over its lanes and cards.
 *
 * ANATOMY, SPACING AND COLOUR TAXONOMY ARE THE DS's, copied verbatim from
 * `kanban-board/KanbanBoard.tsx` (Figma "Kan-ban in Content Layer",
 * 27631:11154): 340px lanes on `bg-accent`, a 4px coloured top strip, a header
 * carrying title + count pill + sort, a scrollable card stack at `gap-3 px-3
 * pb-3`, and cards on `bg-fp-surface-1b` with the full default → hover → focus →
 * active state set. The `--fp-lane-*` fills and the `--fp-banner-accent-*` alert
 * semantics are the DS's tokens, unchanged.
 *
 * ────────────────────────────────────────────────────────────────────────────
 * DS FOLLOW-UP — this is the fifth documented fork in this prototype, and it
 * exists for exactly the same reason as the other four: the DS component cannot
 * be pointed at another dataset. `KanbanBoard` takes NO props at all. Its lanes,
 * its lane colours, its card fields and even the card title ("Card Title") are
 * module-level constants, so a real board cannot use it.
 *
 * What to parameterise, precisely:
 *   1. `lanes: Lane[]` as a prop instead of the `LANES` constant.
 *   2. A card TITLE and an optional title-row aside (this board puts a status
 *      or urgency badge there); today the title is a hardcoded string.
 *   3. `onCardClick` — the DS card is already `role="button" tabIndex={0}` with
 *      a full focus ring, i.e. it is dressed as interactive but does nothing.
 *      Keyboard activation (Enter/Space) is missing too and is added here.
 *   4. Lane sort as a controlled pair (`sortDir`, `onToggleSort`) rather than a
 *      dead icon button.
 *   5. An empty-lane state. A Kanban lane is empty routinely, not exceptionally.
 *   6. Alert TEXT as a prop — the DS hardcodes "Make more happen".
 *   7. A BUG, not a missing prop: the card needs `shrink-0`. The DS card is a
 *      shrinkable flex child of the lane's `overflow-y-auto` stack, so once a
 *      lane holds more cards than fit, the cards COMPRESS instead of the lane
 *      scrolling — and `overflow-hidden` on the card then hides the evidence.
 *      MEASURED here: 8 cards in a 373px lane produced a 34.4px card box around
 *      188px of content, with the lane's scrollHeight equal to its height. The
 *      DS demo hides this because its lanes hold 1–3 cards and never overflow.
 *      Fix it in `kanban-board/KanbanBoard.tsx` too, independently of the props.
 *   8. A SECOND BUG: the lane count pill is `text-white` on the lane fill, which
 *      fails WCAG AA on five of the ten lane colours. Measured at 11px — yellow
 *      1.92, green 2.28, cyan 2.43, rose 3.67, blue 3.68, indigo 4.47, slate
 *      4.76 — and identical in both themes, since `--fp-lane-*` does not change
 *      with the theme. The DS demo already ships the yellow one. Either give the
 *      pill a neutral fill (what this file does) or pair each lane colour with a
 *      measured on-colour foreground token; `text-white` for all ten cannot work.
 * When those eight land, delete this file; do not maintain it in parallel.
 * ────────────────────────────────────────────────────────────────────────────
 */

/** The DS's lane palette, verbatim. */
export type LaneColor =
  | "grey"
  | "blue"
  | "yellow"
  | "green"
  | "cyan"
  | "purple"
  | "violet"
  | "pink"
  | "orange"
  | "red";

const LANE_BG: Record<LaneColor, string> = {
  grey: "bg-fp-lane-grey",
  blue: "bg-fp-lane-blue",
  yellow: "bg-fp-lane-yellow",
  green: "bg-fp-lane-green",
  cyan: "bg-fp-lane-cyan",
  purple: "bg-fp-lane-purple",
  violet: "bg-fp-lane-violet",
  pink: "bg-fp-lane-pink",
  orange: "bg-fp-lane-orange",
  red: "bg-fp-lane-red",
};

/** The DS's alert accents, verbatim. */
export type AlertStatus = "default" | "caution" | "warning" | "success";

const ALERT_ACCENT: Record<AlertStatus, string> = {
  default: "text-foreground",
  caution: "text-fp-banner-accent-caution",
  warning: "text-fp-banner-accent-warning",
  success: "text-fp-banner-accent-success",
};

/**
 * A LINE IN A STACK. Level is hierarchy, not size for its own sake: 1 is what
 * the unit is about, 2 what qualifies it, 3 the fine print. Three levels is
 * what lets a unit hold three facts without three labels — the customer block
 * reads name / site / address off weight alone.
 */
export interface BoardCardLine {
  text: string;
  level?: 1 | 2 | 3;
}

/** One row of the delivery-product unit: the asset, what goes in it, how much. */
export interface BoardCardRow {
  /** The row's SUBJECT — the tank being filled, or the asset being moved. */
  asset: string;
  /** What is going in. A tank in transit is empty, so a movement puts its TYPE here. */
  product?: string;
  qty?: string;
  /** For a quantity that is not a number — "Top-off" is a decision, not an amount. */
  qtySoft?: boolean;
  /**
   * The unit's own identifier, set under its name. NO "SERIAL" LABEL — a code
   * shaped like `FP-TK-0207` under an asset name is not mistakable for anything
   * else, and the word would cost as much width as the number it introduces.
   */
  assetId?: string;
}

/*
  A CARD IS RULED UNITS.

  Each unit is one heading and one shape, divided from the next by a rule. The
  heading is the ONLY label left on the card: inside a unit, hierarchy is
  carried by weight and size, because "Customer / Bray, Raymond and Marks" spends
  a whole line saying what the reader already knows from where it sits.

  Three shapes cover every unit:

    stack   lines at three levels        customer details · delivery partner
    inline  short values, hairline-split schedule — window | cadence
    rows    asset · product · quantity   delivery product details

  `rows` is the one that swaps by kind. A delivery lists its tanks and what goes
  in each; a movement lists the one asset, its type and its capacity. Same three
  columns, so the eye lands in the same place either way.
*/
export type BoardCardUnit =
  | {
      kind: "stack";
      key: string;
      heading: string;
      lines: BoardCardLine[];
      /**
       * A figure that belongs to the unit rather than to one of its lines —
       * what the awarded partner is charging, beside the partner's name. Set
       * in the same size as a quote's price, because on a finished card it is
       * the same fact arriving one stage later.
       */
      figure?: string;
    }
  | { kind: "inline"; key: string; heading: string; parts: string[] }
  | {
      kind: "rows";
      key: string;
      heading: string;
      rows: BoardCardRow[];
      /** Only when more than one row states a number — see `CardRows`. */
      total?: string;
    }
  | {
      kind: "quotes";
      key: string;
      heading: string;
      /** CHEAPEST FIRST — the order is the ranking. See `CardQuotes`. */
      quotes: BoardCardQuote[];
      /** Hide the carrier's name, when the reader has switched it off. */
      nameOff?: boolean;
      /**
       * WHAT THE PRICE IS FOR, folded behind the price itself.
       *
       * Once a partner has been picked the product list has stopped being a
       * question — it is the receipt for a figure, not something the reader is
       * weighing. Set it here and the unit above disappears from the card: the
       * price gains an underline and gives the rows back on a press.
       */
      breakdown?: { rows: BoardCardRow[]; total?: string };
    };

/** One partner's price for the order: who, how much, and where that places them. */
export interface BoardCardQuote {
  vendor: string;
  /** The total landed cost, already formatted. */
  total: string;
  /** 1 is the cheapest. Left out where nothing is being compared — no chip. */
  rank?: number;
}

export interface BoardCardBadge {
  label: string;
  /**
   * `critical` for a state that changes what someone does next.
   *
   * `caution` and `success` are for a state the reader is WAITING ON and one
   * that has ARRIVED — waiting on a partner's price, and having it (Pavan,
   * 2026-09-22). Both take the DS's soft recipe: a `/10` tint of the tone's
   * own hue with the tone's text. A badge on a card is read at a glance from
   * three columns away, so the colour has to carry the difference without
   * becoming the loudest thing on the lane.
   *
   * `info` is the fourth: a state that is simply TRUE of the order and asks
   * nothing of anybody — assigned, under way. It is blue because blue is the
   * one channel in this system that carries no verdict; grey would say the
   * state is unremarkable, and half of these are the states a dispatcher
   * scans for. (Added 2026-09-23.)
   */
  tone?: "critical" | "neutral" | "caution" | "success" | "info";
}

/* THE BADGE IS THE DS PILL (Pavan, 2026-10-09) — the tone is a kind, and
   the pill draws every kind the same way it does in a table cell. */

export interface BoardCard {
  id: string;
  title: string;
  /**
   * The order's TYPE, as a coloured initial beside its number — the DS's
   * `CodeDisc`, the same one the Sales table uses, so D and E mean the same
   * thing in both modules.
   *
   * It sits next to the number because that is where the association is made:
   * `M-104620` and a violet M are one identity, read in one glance. As a line
   * of its own under the title it was a second label for something the reader
   * had already been told.
   */
  code?: { text: string; label: string; tone: CodeDiscTone };
  /**
   * Stacked, not one-of. Priority and recurrence are independent facts and a
   * single slot made them compete — an urgent recurring order lost one.
   *
   * Delivery vs Movement is NOT a badge: the order number's prefix already
   * carries it (`D-` / `M-`), so spending a badge on it says nothing new.
   */
  badges?: BoardCardBadge[];
  /**
   * Under the title: the one fact that makes THIS order what it is, where it
   * has one. A movement puts its route here — where the asset is going IS the
   * order. The category is not a subtitle; it is the code disc.
   */
  subtitle?: string[];
  units: BoardCardUnit[];
  alert?: {
    status: AlertStatus;
    text: string;
    /** Renders a button and splits the footer left/right, per the DS variant. */
    actionLabel?: string;
    onAction?: () => void;
  };
  /**
   * The bottom-most row: where one piece of business on this card has got to,
   * named on the left, with whatever moves it on at the right.
   *
   * ONE STATE AT A TIME. It is a single row with a single label, not a stack —
   * "Request invoice" and "Invoice received" are two points on one line, not
   * two things to do. Omit `actionLabel` for the state that is waiting on
   * somebody else: there is nothing to press, so there is no button.
   *
   * NOT AN ALERT. An alert reports a condition that has arisen — a credit
   * hold, a missing acknowledgement. This is a step the stage always has.
   */
  footerAction?: {
    label: string;
    /** Absent = the row is a status line, waiting on the other side. */
    /**
     * A NODE, NOT A STRING (2026-09-23). The act sometimes wants an icon
     * beside its word — "Assign" with a person is read before it is read —
     * and a `string` forced every such control to be a bare word or a
     * bespoke footer.
     */
    actionLabel?: React.ReactNode;
    actionVariant?: "success" | "outline";
    onAction?: () => void;
    /** Quiet, with a tick — the ball is not in our court. */
    waiting?: boolean;
  };
}

export interface BoardLane {
  key: string;
  title: string;
  color: LaneColor;
  cards: BoardCard[];
  /** Shown in place of the card stack when the lane is empty. */
  emptyLabel?: string;
  /**
   * Starts a new group: a rule is drawn before this lane.
   *
   * A BOARD IS READ LEFT TO RIGHT, and that reading is a claim — that each
   * lane follows from the one before it. Where that stops being true the board
   * has to say so, or the lanes after the break are read as the end of the
   * line rather than as somewhere else entirely. A gap alone does not do it:
   * lanes are already separated by one, so a wider one reads as a mistake.
   */
  apart?: boolean;
}

/** One named way to order a lane — see `BrokerBoardProps.laneSortOptions`. */
export interface LaneSortOption {
  key: string;
  label: string;
}

export interface BrokerBoardProps {
  lanes: BoardLane[];
  onOpenCard?: (id: string) => void;
  /**
   * THE WAYS THIS LANE CAN BE ORDERED, NAMED.
   *
   * The control was a three-state icon that cycled earliest / latest / off on
   * one hidden key, planned time — a button that changed the order of the work
   * without ever saying by what, and whose third press was a state nobody
   * could see they had reached. A lane is a queue, and which end of a queue you
   * work from is a decision with a reason: earliest first while you are
   * dispatching, largest first while you are pricing. The reason is the label.
   *
   * The options are the CALLER'S, because they belong to the lane: what you
   * would sort Draft by is not what you would sort Assigned by.
   */
  laneSortOptions?: (laneKey: string) => LaneSortOption[];
  /** Chosen option per lane key. Absent = the lane's own order. */
  laneSort?: Record<string, string | undefined>;
  onLaneSortChange?: (laneKey: string, option: string | null) => void;
}

/** The unit heading — the only label left on the card. */
function UnitHeading({ children }: { children: React.ReactNode }) {
  return (
    <span className="text-[10px] font-semibold tracking-[0.14em] text-muted-foreground uppercase">
      {children}
    </span>
  );
}

const LEVEL_CLASS: Record<1 | 2 | 3, string> = {
  1: "text-sm font-semibold text-foreground",
  2: "text-[13px] font-medium text-muted-foreground",
  3: "text-xs text-muted-foreground",
};

/** Lines at three levels. Hierarchy does the work a field label used to. */
function CardStack({ lines, figure }: { lines: BoardCardLine[]; figure?: string }) {
  const stack = (
    <div className="flex min-w-0 flex-col">
      {/* KEYED BY POSITION, NOT BY TEXT. Two lines in a unit can legitimately
          read the same — an asset called "Lube Skid" whose type is "Lube Skid"
          — and React then drops one of them and warns about it. Position is
          what a stack's identity actually is: these lines never reorder. */}
      {lines.map((l, i) => (
        <span key={i} className={cn("truncate", LEVEL_CLASS[l.level ?? 1])} title={l.text}>
          {l.text}
        </span>
      ))}
    </div>
  );
  if (!figure) return stack;
  /* THE NAME AND THE FIGURE AT THE TWO EDGES, exactly as the quote unit sets
     them — a finished order's price is the same fact as a quote's, one stage
     on, and it would be strange for it to sit somewhere else on the card. */
  return (
    <div className="flex min-w-0 items-start justify-between gap-2.5">
      {stack}
      <span className="text-lg font-semibold tabular-nums whitespace-nowrap text-foreground">
        {figure}
      </span>
    </div>
  );
}

/**
 * Short values on one line, split by a hairline.
 *
 * A rule rather than a middot because these are two DIFFERENT facts — a window
 * and a cadence — not one list. The hairline reads as a boundary; a dot reads
 * as punctuation inside a single value.
 */
function CardInline({ parts }: { parts: string[] }) {
  return (
    <div className="flex min-w-0 items-center gap-2.5">
      {parts.map((p, i) => (
        <React.Fragment key={p}>
          {i > 0 && <span aria-hidden className="h-3.5 w-px shrink-0 bg-fp-outline-2" />}
          <span
            className={cn(
              "truncate",
              i === 0
                ? "text-[13px] font-medium whitespace-nowrap text-foreground"
                : "text-[13px] text-muted-foreground"
            )}
            title={p}
          >
            {p}
          </span>
        </React.Fragment>
      ))}
    </div>
  );
}

/**
 * Asset · product · quantity, one row each. NO COLUMN HEADINGS — the weights
 * separate them: the asset is the row's subject and takes the ink, the product
 * sits back a step, the quantity is the figure and is set to line up.
 *
 * The total appears only when the per-row figures have stopped answering "how
 * much is coming" — with one row the quantity IS the total, and with every row
 * a top-off there is nothing to add.
 */
function CardRows({ rows, total }: { rows: BoardCardRow[]; total?: string }) {
  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      {rows.map((r, i) => (
        <div
          key={`${r.asset}-${i}`}
          className="grid min-w-0 items-baseline gap-2.5"
          style={{ gridTemplateColumns: "minmax(0,1fr) minmax(0,1.05fr) auto" }}
        >
          {/* NAME OVER ID. The id is the thing you read second — when you are
              already at the right row and need to know which unit it is. */}
          <span className="flex min-w-0 flex-col gap-0.5">
            <span className="truncate text-[13px] font-medium text-foreground" title={r.asset}>
              {r.asset}
            </span>
            {r.assetId && (
              <span className="truncate font-mono text-[11px] text-muted-foreground">
                {r.assetId}
              </span>
            )}
          </span>
          <span className="truncate text-xs text-muted-foreground" title={r.product}>
            {r.product}
          </span>
          <span
            className={cn(
              "text-right text-[13px] tabular-nums whitespace-nowrap",
              r.qtySoft ? "font-medium text-muted-foreground" : "font-semibold text-foreground"
            )}
          >
            {r.qty}
          </span>
        </div>
      ))}
      {total && (
        <div className="flex items-baseline justify-between gap-3 border-t border-dashed border-fp-outline-1 pt-1.5">
          <span className="text-xs text-muted-foreground">Total</span>
          <span className="text-[13px] font-semibold tabular-nums text-foreground">{total}</span>
        </div>
      )}
    </div>
  );
}

/**
 * WHAT THE PARTNERS HAVE QUOTED, one at a time.
 *
 * A card that said "2 accepted — no quote taken yet" while two prices were
 * sitting in the order was not summarising the order, it was contradicting it.
 * The prices are the reason anyone opens these cards, so they go ON the card.
 *
 * ONE AT A TIME, CHEAPEST FIRST. Every quote stacked would be three rows of
 * money on a card whose other four units get one apiece, and the answer to
 * "what will this cost" is a single figure — the best one. The others are a
 * step away rather than a scroll away, so the reader chooses to compare rather
 * than being made to.
 *
 * THE PLACE IS SPELLED OUT, not left to the order of a list nobody can see the
 * whole of: on the second card the figure alone cannot say whether it is the
 * cheap one or the dear one, and "2nd best" can.
 */
function rankLabel(rank: number): string {
  if (rank === 1) return "Best price";
  const n = rank % 100;
  const suffix =
    n >= 11 && n <= 13
      ? "th"
      : rank % 10 === 1
        ? "st"
        : rank % 10 === 2
          ? "nd"
          : rank % 10 === 3
            ? "rd"
            : "th";
  return `${rank}${suffix} best`;
}

function CardQuotes({
  heading,
  quotes,
  nameOff,
  breakdown,
}: {
  heading: string;
  quotes: BoardCardQuote[];
  nameOff?: boolean;
  breakdown?: { rows: BoardCardRow[]; total?: string };
}) {
  const [i, setI] = React.useState(0);
  const at = Math.min(i, quotes.length - 1);
  const q = quotes[at];
  /* THE CARD IS THE BUTTON, so every control on it has to say so and stop.
     Without this, stepping to the next quote opens the order. */
  const step = (e: React.SyntheticEvent, d: number) => {
    e.stopPropagation();
    setI((v) => Math.max(0, Math.min(quotes.length - 1, v + d)));
  };
  const chevron =
    "rounded-sm p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-30";

  return (
    <>
      <div className="flex items-center justify-between gap-2">
        <UnitHeading>{heading}</UnitHeading>
        {quotes.length > 1 && (
          <span
            className="flex items-center gap-0.5 text-[10px] tabular-nums text-muted-foreground"
            onClick={(e) => e.stopPropagation()}
          >
            <button
              type="button"
              aria-label="Previous quote"
              disabled={at === 0}
              onClick={(e) => step(e, -1)}
              onKeyDown={(e) => e.stopPropagation()}
              className={chevron}
            >
              <ChevronLeft className="size-3" />
            </button>
            {at + 1}/{quotes.length}
            <button
              type="button"
              aria-label="Next quote"
              disabled={at === quotes.length - 1}
              onClick={(e) => step(e, 1)}
              onKeyDown={(e) => e.stopPropagation()}
              className={chevron}
            >
              <ChevronRight className="size-3" />
            </button>
          </span>
        )}
      </div>
      {/* THE NAME AND THE FIGURE ON ONE LINE, the placing under the name —
          the two things being compared sit at the two edges, and the label
          that qualifies the name hangs off it rather than off the money. */}
      <div className="flex min-w-0 items-start justify-between gap-2.5">
        <span className="flex min-w-0 flex-col gap-0.5">
          {!nameOff && (
            <span className="truncate text-sm font-semibold text-foreground" title={q.vendor}>
              {q.vendor}
            </span>
          )}
          {/* THE PLACING IS A CHIP, not a caption. It is a verdict on the
              figure beside it — the one thing on the unit that says whether
              this price is the one to take — and as loose text under the
              carrier's name it read as a second line of the name. Green for
              the cheapest, because that is the only placing anyone acts on;
              the rest are neutral, so a board of chips does not turn into a
              ranking nobody asked to see. */}
          {q.rank !== undefined && (
          <Pill kind={q.rank === 1 ? "success" : "neutral"} className="self-start">
            {rankLabel(q.rank)}
          </Pill>
          )}
        </span>
        {/* BIGGER THAN ANYTHING ELSE ON THE CARD. The figure is the reason
            these cards get opened, and at 13px it was the same size as an
            asset name. `text-lg` is the nearest step on the scale. */}
        {breakdown ? (
          <Popover>
            <PopoverTrigger asChild>
              <button
                type="button"
                /* THE CARD IS THE BUTTON, so this one has to say so and stop —
                   without it, asking what the price is for opens the order. */
                onClick={(e) => e.stopPropagation()}
                onKeyDown={(e) => e.stopPropagation()}
                aria-label={`${q.total} — what this is for`}
                className="rounded-sm text-lg font-semibold tabular-nums whitespace-nowrap text-foreground underline decoration-fp-outline-1 decoration-dotted underline-offset-4 outline-none transition-colors hover:decoration-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
              >
                {q.total}
              </button>
            </PopoverTrigger>
            <PopoverContent
              align="end"
              className="w-72 p-3"
              onClick={(e) => e.stopPropagation()}
            >
              {/* THE UNIT'S OWN HEADING COMES WITH IT. Opened from a figure
                  with no name on it, a bare list of tanks is three numbers
                  belonging to nothing. */}
              <UnitHeading>Delivery Product Details</UnitHeading>
              <div className="mt-2">
                <CardRows rows={breakdown.rows} total={breakdown.total} />
              </div>
            </PopoverContent>
          </Popover>
        ) : (
          <span className="text-lg font-semibold tabular-nums whitespace-nowrap text-foreground">
            {q.total}
          </span>
        )}
      </div>
    </>
  );
}

function CardAlert({
  status,
  text,
  actionLabel,
  onAction,
}: NonNullable<BoardCard["alert"]>) {
  return (
    <div
      className={cn(
        "flex items-center gap-2 border-t border-fp-outline-1 px-3 py-2",
        actionLabel ? "justify-between" : "justify-center"
      )}
    >
      <span className={cn("flex min-w-0 items-center gap-2 text-xs", ALERT_ACCENT[status])}>
        <Info className="size-4 shrink-0" />
        <span className="truncate">{text}</span>
      </span>
      {actionLabel && (
        <Button
          variant="outline"
          size="xs"
          onClick={(e) => {
            // The card itself is clickable; a footer action must not also open it.
            e.stopPropagation();
            onAction?.();
          }}
        >
          {actionLabel}
        </Button>
      )}
    </div>
  );
}

function Card({ card, onOpen }: { card: BoardCard; onOpen?: () => void }) {
  return (
    <div
      role="button"
      tabIndex={0}
      aria-label={`Open ${card.title}`}
      onClick={onOpen}
      // The DS card is already dressed as a button but has no activation. A
      // focus ring that leads nowhere on Enter is worse than no ring at all.
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onOpen?.();
        }
      }}
      className={cn(
        // `shrink-0` is NOT cosmetic — see the DS FOLLOW-UP note (7) at the top
        // of this file. Without it the card is a shrinkable flex child inside the
        // lane's scroll container, so a full lane compresses every card to its
        // title row and clips the rest under `overflow-hidden` instead of
        // scrolling. MEASURED: 8 cards in a 373px lane gave a 34.4px box around
        // 188px of content, and the lane's scrollHeight equalled its height, so
        // nothing scrolled and nothing hinted that content was missing.
        "shrink-0",
        "cursor-pointer overflow-hidden rounded-md border border-fp-outline-1 bg-fp-surface-1b outline-none transition-[color,border-color,box-shadow]",
        "hover:border-fp-outline-2 hover:shadow-fp-surface",
        "focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50",
        "active:border-fp-outline-2 active:bg-fp-card-1"
      )}
    >
      {/* UNITS ARE RULED. A rule per unit is affordable here because there are
          five of them and each holds ONE shape — the rules are what let the
          headings shrink to 10px and the field labels disappear entirely. */}
      <div className="flex flex-col gap-1 p-3.5">
        <div className="flex items-start justify-between gap-2">
          <div className="flex min-w-0 items-center gap-1.5">
            <h4 className="min-w-0 truncate font-mono text-sm font-semibold text-foreground">
              {card.title}
            </h4>
            {card.code && (
              <CodeDisc
                code={card.code.text}
                label={card.code.label}
                tone={card.code.tone}
                className="shrink-0"
              />
            )}
          </div>
          {card.badges && card.badges.length > 0 && (
            <div className="flex shrink-0 flex-wrap justify-end gap-1">
              {card.badges.map((b) => (
                <Pill key={b.label} kind={b.tone ?? "neutral"}>
                  {b.label}
                </Pill>
              ))}
            </div>
          )}
        </div>
        {card.subtitle?.map((line) => (
          <span key={line} className="truncate text-xs text-muted-foreground" title={line}>
            {line}
          </span>
        ))}
      </div>

      {card.units.map((u) => (
        <div
          key={u.key}
          className="flex flex-col gap-1.5 border-t border-fp-outline-1 p-3.5"
        >
          {/* The quotes unit draws its own heading row — the stepper sits
              on the line with the label, where a unit's controls belong. */}
          {u.kind === "quotes" ? (
            <CardQuotes
              heading={u.heading}
              quotes={u.quotes}
              nameOff={u.nameOff}
              breakdown={u.breakdown}
            />
          ) : (
            <>
              <UnitHeading>{u.heading}</UnitHeading>
              {u.kind === "stack" && <CardStack lines={u.lines} figure={u.figure} />}
              {u.kind === "inline" && <CardInline parts={u.parts} />}
              {u.kind === "rows" && <CardRows rows={u.rows} total={u.total} />}
            </>
          )}
        </div>
      ))}

      {/* NO "VIEW DETAILS" ROW. The whole card opens the order — it is the
          button — so a strip at the bottom naming that was a label for a thing
          the reader was already standing on, and it cost every card a rule and
          25px to say it. What is left in this footer is what the card is
          waiting on: an alert, or the invoice row. */}
      {card.alert && <CardAlert {...card.alert} />}

      {card.footerAction && (
        <div className="flex items-center justify-between gap-2 border-t border-fp-outline-1 px-3.5 py-2.5">
          {card.footerAction.waiting ? (
            <span className="flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground">
              <Check className="size-3.5 shrink-0" />
              <span className="truncate">{card.footerAction.label}</span>
            </span>
          ) : (
            <span className="truncate text-xs text-foreground">
              {card.footerAction.label}
            </span>
          )}
          {card.footerAction.actionLabel && (
            /* FILLED, NOT OUTLINED, for the step that moves the order on. Every
               other control on a card is an outline or a plain word, so an
               outline here read as one more thing to look at rather than the
               thing to press. */
            <Button
              variant={card.footerAction.actionVariant ?? "success"}
              size="xs"
              onClick={(e) => {
                /* The card itself opens the order; this must not. */
                e.stopPropagation();
                card.footerAction?.onAction?.();
              }}
            >
              {card.footerAction.actionLabel}
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

function Lane({
  lane,
  onOpenCard,
  sortOptions,
  sortKey,
  onSortChange,
}: {
  lane: BoardLane;
  onOpenCard?: (id: string) => void;
  sortOptions?: LaneSortOption[];
  sortKey?: string;
  onSortChange?: (option: string | null) => void;
}) {
  const chosen = sortOptions?.find((o) => o.key === sortKey);
  return (
    /* 400px, not the DS's 340. The card's product unit is three columns —
       asset, product, quantity — and at 340 the first two truncated on any
       real pair of names. The lane widened to fit the content rather than the
       content being cut to fit the lane. */
    <div data-fp-unit="lane" className="flex h-full w-(--fp-board-lane-width) shrink-0 flex-col overflow-hidden rounded-md bg-fp-board-lane">
      <div className={cn("h-1 w-full shrink-0", LANE_BG[lane.color])} aria-hidden />
      <div className="flex shrink-0 items-center gap-2 px-4 py-3">
        <h3 className="min-w-0 truncate text-sm font-semibold text-foreground">
          {lane.title}
        </h3>
        {/* COUNT PILL — see DS FOLLOW-UP (8). The DS Kanban fills this pill with
            the lane colour and sets the label `text-white`, which is unreadable
            on the lighter half of the lane palette. MEASURED, 11px text:
            yellow 1.92 · green 2.28 · cyan 2.43 · rose 3.67 · blue 3.68 ·
            indigo 4.47 · slate 4.76 — five of the seven lanes used here fail
            WCAG AA, and the numbers are identical in both themes because the
            lane fills do not change with the theme.

            This uses the count-pill recipe the rest of the system already has —
            `bg-fp-card-1` + a neutral label, exactly as `ListToolbar`'s column
            counter and `ColumnSearchChip` do — rather than inventing a colour.
            The lane's identity still reads from its 4px top strip, which is
            where the lane colour is load-bearing. It is `aria-hidden` because
            the `sr-only` count below already says it. */}
        <span
          aria-hidden
          className="inline-flex min-w-5 shrink-0 items-center justify-center rounded-full bg-fp-card-1 px-1 text-[11px] font-medium tabular-nums text-foreground"
        >
          {lane.cards.length}
        </span>
        <span className="sr-only">{lane.cards.length} orders</span>
        {sortOptions && sortOptions.length > 0 && onSortChange && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button
                type="button"
                aria-label={`Sort ${lane.title}${chosen ? ` — ${chosen.label}` : ""}`}
                className={cn(
                  "ml-auto shrink-0 rounded-sm p-1 outline-none transition-colors hover:bg-fp-card-1 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 data-[state=open]:text-foreground",
                  chosen ? "text-foreground" : "text-muted-foreground"
                )}
              >
                <ArrowDownUp className="size-4" />
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-60">
              <DropdownMenuLabel className="text-[11px] font-normal text-muted-foreground">
                Sort {lane.title.toLowerCase()} by
              </DropdownMenuLabel>
              <DropdownMenuRadioGroup
                value={sortKey ?? ""}
                onValueChange={(v) => onSortChange(v === "" ? null : v)}
              >
                {/* THE LANE'S OWN ORDER IS ONE OF THE CHOICES, not the absence
                    of one. A sort you can turn on and cannot name your way out
                    of is a sort you are stuck with. */}
                <DropdownMenuRadioItem value="">
                  Lane order
                </DropdownMenuRadioItem>
                {sortOptions.map((o) => (
                  <DropdownMenuRadioItem key={o.key} value={o.key}>
                    {o.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>
      <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto px-3 pb-3">
        {lane.cards.length === 0 ? (
          <p className="px-1 py-2 text-xs text-muted-foreground">
            {lane.emptyLabel ?? "Nothing here"}
          </p>
        ) : (
          lane.cards.map((card) => (
            <Card key={card.id} card={card} onOpen={() => onOpenCard?.(card.id)} />
          ))
        )}
      </div>
    </div>
  );
}

export function BrokerBoard({
  lanes,
  onOpenCard,
  laneSortOptions,
  laneSort,
  onLaneSortChange,
}: BrokerBoardProps) {
  return (
    <div className="flex h-full min-h-0 gap-4 overflow-x-auto pb-1">
      {lanes.map((lane) => (
        <React.Fragment key={lane.key}>
          {/* THE RULE IS THE BREAK, and the air around it is what makes it one:
              8px either side on top of the row's own 16px gap, so the two
              groups are 49px apart where lanes within a group are 16. It runs
              the full height of the board rather than the height of a lane,
              because it divides the BOARD — a rule that stopped where the
              tallest lane did would read as a border on the lane beside it. */}
          {lane.apart && (
            /* 3px AND THE STRONGER OUTLINE. A hairline is what separates two
               things of the same kind — a column from a column, a row from a
               row — and this separates two KINDS, so at 1px it read as a lane
               border somebody had left on. It is the only vertical rule on the
               board, so it can afford to be the heaviest thing on it. */
            <div
              className="mx-3 w-[3px] shrink-0 self-stretch rounded-full bg-fp-outline-2"
              aria-hidden
            />
          )}
          <Lane
            lane={lane}
            onOpenCard={onOpenCard}
            sortOptions={laneSortOptions?.(lane.key)}
            sortKey={laneSort?.[lane.key]}
            onSortChange={
              onLaneSortChange ? (o) => onLaneSortChange(lane.key, o) : undefined
            }
          />
        </React.Fragment>
      ))}
    </div>
  );
}

import type { ActivityEntry } from "./activity";

/**
 * Sales Console — Fuel Orders types.
 *
 * Structure and field names come from the FleetPanda Sales Console (the app
 * being recreated); every *visual* treatment comes from the DS.
 */
/**
 * THE ORDER'S STAGE (Pavan, 2026-10-07, taken from the Lovable Sales app):
 * Requested → Scheduled → Dispatched → Delivered, or Canceled. Replaces the
 * old Assigned / Unassigned, which only said whether a driver was picked.
 */
export type CoreFuelStage = "Requested" | "Scheduled" | "Dispatched" | "Delivered" | "Canceled";
/* A STAGE IS AN ID, NOT ONE OF FIVE WORDS (Pavan, 2026-10-07). Sales
   Settings can add stages between the five, so an order's stage is the core
   name or an added stage's `stage-…` id; `stageLabel` prints it. */
export type FuelOrderStatus = CoreFuelStage | (string & {});

/** Order type. The list column renders the code; the label is the tooltip. */
export type OrderTypeCode = "D" | "E";

export interface OrderType {
  code: OrderTypeCode;
  label: "Delivery" | "Extraction";
}

/**
 * When the delivery is planned. Rendered as two lines — date over time — and no
 * longer a from/to range.
 */
export interface PlannedAt {
  /** Formatted date, e.g. "Aug 24, 2026". */
  date: string;
  /** Formatted 12-hour time, e.g. "1:35 AM". */
  time: string;
}

/**
 * One product line on an order, with its own gallons. The row's Qty (Gal) is the
 * sum, and hovering it reveals this breakdown when there is more than one line.
 */
export interface ProductQty {
  name: string;
  gal: number;
}

/** Two-line cell: primary over a muted secondary. */
export interface TwoLine {
  title: string;
  description: string;
}

/** Person cell — initials avatar + name. `null` renders "— Unassigned". */
export interface Person {
  name: string;
  /** Avatar fallback initials, e.g. "ST". */
  initials: string;
}

export interface FuelOrder {
  id: string;
  /** col "Order #" — order number and the type badge share one cell */
  orderNo: string;
  type: OrderType;
  /** col "Customer" — customer name over ship-to */
  customer: TwoLine;
  /** col "Product" — product lines; the cell truncates past `PRODUCTS_SHOWN` */
  products: ProductQty[];
  /** col "Qty (Gal)" — the sum of `products`, derived when rows are built */
  qtyGal: number;
  /** col "Date of Delivery" — delivery date over its relative form */
  date: TwoLine;
  /** `YYYY-MM-DD` of the delivery date — what the toolbar date filter matches. */
  dateKey: string;
  /** col "Planned Date & Time" — date over time, or `null` for an em-dash */
  planned: PlannedAt | null;
  /** col "Tags" — free-form labels; the cell truncates past what fits */
  tags: string[];
  /** col "Status" */
  status: FuelOrderStatus;
  /** col "Driver" — `null` renders "— Unassigned" */
  driver: Person | null;
  /** The sheet's "Mark as Urgent" — kept on the order since 2026-10-07. */
  urgent: boolean;
  /** The change log — see `activity.tsx`. Written by the screen's setter. */
  audit?: ActivityEntry[];
  /* SALES SETTINGS' FIELDS (Pavan, 2026-10-07). What a field added on Form
     customization holds, by its key. */
  extra?: Record<string, string | boolean>;
  /** ISO — when the order entered its stage. The SLA clock. */
  stageSince?: string;
  /** The quote this order was made from, when it was. */
  fromQuote?: string;
  /** A move asked for and waiting on approval — the stage it would go to. */
  approvalFor?: string;
}

/**
 * The signed-in account. One shape for the top bar's avatar/menu and the
 * Profile page, so an edit on Profile is visible in the chrome immediately.
 * Structurally the DS's `TopBarUser`, restated here because the prototype owns
 * the state and the DS type is a prop contract, not a model.
 */
export interface AccountUser {
  name: string;
  email: string;
  /** Avatar fallback initials, e.g. "PS". */
  fallback: string;
  avatarSrc?: string;
}

import * as React from "react";
import { Check, ChevronDown, Trash2, X } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";

/*
  Editable table cells — Figma "Input / Dropdown Tables Layout"
  (27593:15012 / 27592:33634).

  THE RULE THESE ENCODE: a cell in an editable table has NO control chrome of
  its own. It fills the whole `td`, and its states are carried by the cell —
  hover lifts to `--accent`, focus washes to Surface-1a with an inset ring. A
  bordered input or select dropped inside a padded cell puts a box inside a box:
  the table already draws the grid, so the control redrawing it is the second
  border, and the cell's real edges stop being the thing you read.

  Extracted from `EditableTable`, which was the only place they existed, so a
  real form's table can follow the same idiom instead of nesting controls.

  The parent `td` must be `relative` and `p-0` — a table cell gives no definite
  height for `h-full` to resolve against, so `inset-0` is what makes the state
  surface span the cell.
*/

/** Required-column marker for a table header. */
export function TableRequiredLabel({
  children,
  required,
}: {
  children: React.ReactNode;
  required?: boolean;
}) {
  /* NEVER WRAPS. A column heading that breaks onto a second line stops sitting
     over the column it names, and the table reads as though its headers have
     slipped — which is exactly what it looks like. A heading too long for its
     column is a column that is too narrow, and that is fixed in the colgroup. */
  return (
    <span className="text-sm font-medium whitespace-nowrap text-foreground">
      {children}
      {required && <span className="text-destructive"> *</span>}
    </span>
  );
}

export interface TableCellSelectProps {
  value: string;
  options: string[];
  /**
   * Second line under the value. A NODE, not just a string: a cell's second
   * line is often a state — a chip saying this partner will never see the
   * invitation — and the alternative was floating that chip over the cell,
   * where a narrow column laid it on top of the name.
   */
  description?: React.ReactNode;
  placeholder?: string;
  disabled?: boolean;
  /** Option count at or above which the search field appears. Default: always. */
  searchThreshold?: number;
  onChange: (v: string) => void;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
  /**
   * PICK SEVERAL AT ONCE, AND APPLY THEM.
   *
   * A list of rows you fill one at a time asks for the same three gestures per
   * row — open, choose, open the next — when the thing being said is "these
   * five". With this the options carry checkboxes and the list keeps a footer
   * with Apply: one open, one Apply, and the caller decides what several
   * choices mean (here: fill this row and add a row per extra).
   *
   * Pass it only where a row can legitimately become many. Left off, the cell
   * writes one value and closes, which is what a cell replacing its own
   * contents should do.
   */
  multiple?: {
    /** Already chosen elsewhere in the list — shown ticked and read-only. */
    taken?: string[];
    onApply: (picked: string[]) => void;
  };
}

/**
 * A cell that opens a list and writes the choice back. No visible control.
 *
 * The list SEARCHES, like every other list in this system. Scrolling a cell's
 * popover for a name you already know is the slowest way to answer it, and a
 * cell that sometimes takes typing and sometimes does not is one you have to
 * open before you know which. `searchThreshold` can still suppress it.
 */
export function TableCellSelect({
  value,
  options,
  description,
  placeholder = "Select",
  disabled,
  searchThreshold = 1,
  onChange,
  "aria-label": ariaLabel,
  multiple,
  autoFocus,
}: TableCellSelectProps) {
  const [open, setOpen] = React.useState(false);
  const showSearch = options.length >= searchThreshold;
  /* THE TICKS ARE THE POPOVER'S, not the record's. Nothing is written until
     Apply, so closing the list without pressing it changes nothing — which is
     the difference between choosing and having chosen. */
  const [picked, setPicked] = React.useState<string[]>([]);
  React.useEffect(() => {
    if (!open) setPicked([]);
  }, [open]);
  const toggle = (opt: string) =>
    setPicked((prev) =>
      prev.includes(opt) ? prev.filter((x) => x !== opt) : [...prev, opt]
    );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild disabled={disabled}>
        <button
          type="button"
          aria-label={ariaLabel}
          autoFocus={autoFocus}
          className={cn(
            "absolute inset-0 flex items-center justify-between gap-2 px-3 text-left transition-colors outline-none",
            "hover:bg-accent focus-visible:bg-fp-surface-1a focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
          )}
        >
          <span className="flex min-w-0 flex-col">
            <span
              className={cn(
                "truncate text-sm",
                value ? "text-foreground" : "text-muted-foreground"
              )}
            >
              {value || placeholder}
            </span>
            {description && (
              /* `items-start` so a chip on this line keeps its own width
                 instead of stretching to the cell. */
              <span className="flex items-start truncate text-xs text-muted-foreground">
                {description}
              </span>
            )}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          {showSearch && <CommandInput placeholder="Search…" />}
          <CommandList>
            <CommandEmpty>No options.</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => {
                const used = Boolean(multiple?.taken?.includes(opt)) && opt !== value;
                return (
                <CommandItem
                  key={opt}
                  value={opt}
                  disabled={used}
                  onSelect={() => {
                    if (used) return;
                    if (multiple) {
                      toggle(opt);
                      return;
                    }
                    onChange(opt);
                    setOpen(false);
                  }}
                >
                  {multiple && (
                    <Checkbox
                      checked={used || picked.includes(opt)}
                      /* The row is the control; the box reports it. */
                      tabIndex={-1}
                      aria-hidden
                      className="pointer-events-none"
                    />
                  )}
                  {opt}
                </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
          {multiple && (
            /* THE COUNT AND THE ACT, on one line. Apply is disabled with
               nothing ticked rather than hidden: a footer that appears and
               disappears makes the list jump as you choose. */
            <div className="flex items-center justify-between gap-2 border-t border-border p-1 pl-2.5">
              <span className="text-xs tabular-nums text-muted-foreground">
                {picked.length} selected
              </span>
              <Button
                size="sm"
                variant="ghost"
                disabled={picked.length === 0}
                onClick={() => {
                  multiple.onApply(picked);
                  setOpen(false);
                }}
              >
                Apply
              </Button>
            </div>
          )}
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export interface TableCellInputProps {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  /**
   * A SUGGESTED VALUE (Pavan, 2026-10-20) — shown as the placeholder while the
   * cell is empty; → (ArrowRight) in the empty cell takes it, as an inline
   * completion does. The suggested quantity for a tank, on an order.
   */
  suggestion?: string;
  disabled?: boolean;
  /** Right-align and tabular-align digits, for a quantity or amount column. */
  numeric?: boolean;
  /** Unit shown after the value, e.g. `gal`. Not part of the value. */
  suffix?: string;
  /**
   * Unit shown BEFORE the value, e.g. `$`. Not part of the value.
   *
   * It pins to the cell's left edge while the figure stays right-aligned,
   * which is how every ledger prints money: the symbol marks the column, the
   * digits line up for comparing. Stuck to the number it would move with the
   * number's length and stop marking anything.
   */
  prefix?: string;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
}

/** A free-text cell filling the whole td. Same states as the select. */
export function TableCellInput({
  value,
  onChange,
  placeholder,
  suggestion,
  disabled,
  numeric,
  suffix,
  prefix,
  "aria-label": ariaLabel,
  autoFocus,
}: TableCellInputProps) {
  /*
    WHAT WAS TYPED, UNTIL IT IS FINISHED BEING TYPED.

    These cells are controlled by a NUMBER upstream, and a number cannot hold a
    half-written one. Typing "1.4" sent "1." to the parent, which parsed it to
    1 and handed back "1" — so the decimal point was swallowed on every
    keystroke and no fractional rate could be entered at all. The same is true
    of a leading "0." or a trailing zero.

    While the cell has focus it shows the literal keystrokes and the parent
    still receives every one of them; on blur the buffer is dropped and the
    canonical value comes back, so "1.40" settles to "1.4" and "abc" to
    whatever the parent made of it. The parent stays the source of truth — this
    only stops it answering mid-word.
  */
  const [typed, setTyped] = React.useState<string | null>(null);
  const shown = typed ?? value;
  /*
    A CURRENCY MARK BELONGS TO ITS NUMBER, not to the cell.

    A numeric cell right-aligns its figure and the prefix was pinned to the left
    edge, so "$" and "3.57" sat at opposite ends of a 132px column with nothing
    between them — the mark read as a column header for the cell rather than as
    part of the amount. Right-align the pair instead and close the gap to 4px:
    the "$" travels with the first digit however long the number gets.

    `field-sizing-content` is what lets the input shrink to its own text so the
    prefix can sit against it; the LABEL is still the full-cell click target, so
    nothing is harder to hit. Only `numeric` cells with a prefix change — a text
    cell's input still fills the width, which is where typing should start.
  */
  const moneyish = Boolean(numeric && prefix);
  return (
    <label
      className={cn(
        "absolute inset-0 flex cursor-text items-center px-3 transition-colors",
        moneyish ? "gap-1" : "gap-1.5",
        "hover:bg-accent",
        "focus-within:bg-fp-surface-1a focus-within:ring-2 focus-within:ring-inset focus-within:ring-ring/50",
        disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
      )}
    >
      {prefix && (
        <span className="shrink-0 text-sm text-muted-foreground">{prefix}</span>
      )}
      <input
        type="text"
        value={shown}
        onChange={(e) => {
          setTyped(e.target.value);
          onChange(e.target.value);
        }}
        onBlur={() => setTyped(null)}
        onKeyDown={(e) => {
          if (suggestion && e.key === "ArrowRight" && shown === "") {
            e.preventDefault();
            setTyped(suggestion);
            onChange(suggestion);
          }
        }}
        placeholder={suggestion || placeholder}
        disabled={disabled}
        aria-label={ariaLabel}
        autoFocus={autoFocus}
        className={cn(
          "h-full min-w-0 bg-transparent text-sm text-foreground outline-none",
          "placeholder:text-muted-foreground disabled:cursor-not-allowed",
          numeric && "tabular-nums",
          moneyish ? "w-auto field-sizing-content" : "w-full"
        )}
      />
      {suffix && (
        <span className="shrink-0 text-xs text-muted-foreground">{suffix}</span>
      )}
    </label>
  );
}

export interface TableCellMultiSelectProps {
  values: string[];
  options: string[];
  placeholder?: string;
  disabled?: boolean;
  /**
   * Singular noun for the count summary — "product" prints "3 products". The
   * count is what a narrow cell can hold; the names are in the list one click
   * away, and on the `title` for a pointer that hovers.
   */
  unitLabel?: string;
  /** What the closed cell prints, when the caller shows the rest elsewhere (e.g. as sub-rows). */
  summary?: string;
  onChange: (next: string[]) => void;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
}

/**
 * A cell holding MORE THAN ONE choice — same borderless idiom as the others.
 *
 * It summarises rather than listing: one value prints itself, several print
 * their count. A cell that grew a chip per choice would change the table's row
 * height as it was filled, and a column whose rows are different heights stops
 * being scannable, which is the only reason to put this in a table at all.
 *
 * CHECKBOX ROWS AND AN APPLY (Pavan, 2026-09-24). A list with a trailing tick
 * reads as single-select — the reader picks one and stops (`MultiSelectList`
 * explains why). Ticks are a draft while the list is open; Apply commits them
 * in one go, and closing without it changes nothing.
 */
export function TableCellMultiSelect({
  values,
  options,
  placeholder = "Select",
  disabled,
  unitLabel = "selected",
  summary: summaryOverride,
  onChange,
  "aria-label": ariaLabel,
  autoFocus,
}: TableCellMultiSelectProps) {
  const [open, setOpen] = React.useState(false);
  /* THE DRAFT — what is ticked while the list is open. */
  const [draft, setDraft] = React.useState<string[]>(values);

  const summary =
    summaryOverride ??
    (values.length === 0
      ? placeholder
      : values.length === 1
        ? values[0]
        : `${values.length} ${unitLabel}${unitLabel.endsWith("s") ? "" : "s"}`);

  const toggle = (opt: string) =>
    setDraft((d) => (d.includes(opt) ? d.filter((v) => v !== opt) : [...d, opt]));

  return (
    <Popover
      open={open}
      onOpenChange={(o) => {
        if (o) setDraft(values);
        setOpen(o);
      }}
    >
      <PopoverTrigger asChild disabled={disabled}>
        <button
          type="button"
          aria-label={ariaLabel}
          autoFocus={autoFocus}
          title={values.join(", ") || undefined}
          className={cn(
            "absolute inset-0 flex items-center justify-between gap-2 px-3 text-left transition-colors outline-none",
            "hover:bg-accent focus-visible:bg-fp-surface-1a focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
          )}
        >
          <span
            className={cn(
              "truncate text-sm",
              values.length > 0 ? "text-foreground" : "text-muted-foreground"
            )}
          >
            {summary}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command>
          <CommandInput placeholder="Search…" />
          <CommandList>
            <CommandEmpty>No options.</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => (
                <CommandItem
                  key={opt}
                  value={opt}
                  onSelect={() => toggle(opt)}
                  aria-checked={draft.includes(opt)}
                  icon={
                    <Checkbox
                      checked={draft.includes(opt)}
                      className="pointer-events-none"
                      tabIndex={-1}
                    />
                  }
                >
                  <span className="flex-1 truncate">{opt}</span>
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
        <div className="flex items-center justify-between gap-2 border-t border-border p-2">
          <span className="text-xs text-muted-foreground">
            {draft.length} selected
          </span>
          <Button
            size="sm"
            onClick={() => {
              onChange(options.filter((o) => draft.includes(o)));
              setOpen(false);
            }}
          >
            Apply
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
}

export interface TableCellComboboxProps {
  value: string;
  options: string[];
  placeholder?: string;
  disabled?: boolean;
  /** Allow a value that is not in `options`, offered as its own item. */
  creatable?: boolean;
  /**
   * The words on the right of the typed-value row — "Add as fee". The typed
   * text sits on the left (Pavan, 2026-09-25). Default "Add".
   */
  createLabel?: string;
  /**
   * AN OPTIONAL CELL CAN BE EMPTIED AGAIN (DS ux §Forms, 2026-09-25) — the
   * empty choice, e.g. "No asset", shown first; picking it sets "".
   */
  clearLabel?: string;
  /**
   * Values already used by OTHER rows of the same table. Shown ticked and
   * unselectable rather than hidden: removing them would make the list change
   * length as you fill the table, and someone looking for an asset they already
   * added would conclude it does not exist. Ticked says "here, and already on
   * the order".
   */
  taken?: readonly string[];
  onChange: (v: string) => void;
  /**
   * Take focus when the cell MOUNTS — pass it to the first editable cell of a
   * row the reader has just added, so the add is followed by the answer and
   * not by a hunt for the row (DS ui §10f, "Rows"). Mount-only: rows already
   * on the table are never re-focused.
   */
  autoFocus?: boolean;
  "aria-label"?: string;
  /**
   * PICK SEVERAL, ONE ROW EACH — `TableCellSelect`'s `multiple`, for a cell
   * you can also type into. Checkboxes, a footer with Apply; a typed name is
   * ticked like any other. The caller fills this row with the first and adds a
   * row per extra (DS ui §10f "Picking several makes rows"). Pass it only on a
   * BLANK row: on a filled one the question is "which one instead".
   */
  multiple?: {
    onApply: (picked: string[]) => void;
  };
}

/**
 * A cell you can TYPE INTO or PICK FROM — same borderless idiom as the others.
 *
 * A plain select cannot reach a value the list has not caught up with; a plain
 * input cannot attach to a real record. `creatable` keeps whatever was typed
 * available as its own option, so a new name is one Enter away rather than a
 * second-class path.
 */
export function TableCellCombobox({
  value,
  options,
  placeholder = "Select",
  disabled,
  creatable,
  createLabel = "Add",
  clearLabel,
  taken,
  onChange,
  "aria-label": ariaLabel,
  autoFocus,
  multiple,
}: TableCellComboboxProps) {
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  /* NOTHING IS WRITTEN UNTIL APPLY — as in TableCellSelect. */
  const [picked, setPicked] = React.useState<string[]>([]);
  React.useEffect(() => {
    if (!open) setPicked([]);
  }, [open]);
  const toggle = (v: string) =>
    setPicked((prev) => (prev.includes(v) ? prev.filter((x) => x !== v) : [...prev, v]));

  const matches = options.filter((o) =>
    o.toLowerCase().includes(query.trim().toLowerCase())
  );
  const typedIsNew =
    Boolean(creatable) &&
    query.trim().length > 0 &&
    !options.some((o) => o.toLowerCase() === query.trim().toLowerCase());

  const choose = (v: string) => {
    if (multiple && v) {
      toggle(v);
      setQuery("");
      return;
    }
    onChange(v);
    setQuery("");
    setOpen(false);
  };
  /* Typed names the reader ticked — not in `options`, so listed on their own. */
  const pickedNew = picked.filter((p) => !options.includes(p));

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild disabled={disabled}>
        <button
          type="button"
          aria-label={ariaLabel}
          autoFocus={autoFocus}
          className={cn(
            "absolute inset-0 flex items-center justify-between gap-2 px-3 text-left transition-colors outline-none",
            "hover:bg-accent focus-visible:bg-fp-surface-1a focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
          )}
        >
          <span
            className={cn(
              "truncate text-sm",
              value ? "text-foreground" : "text-muted-foreground"
            )}
          >
            {value || placeholder}
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 p-0">
        <Command shouldFilter={false}>
          <CommandInput
            value={query}
            onValueChange={setQuery}
            placeholder={creatable ? "Type or pick…" : "Search…"}
          />
          <CommandList>
            {typedIsNew && (
              <CommandGroup>
                {/* WHAT WAS TYPED ON THE LEFT, THE ACT ON THE RIGHT (Pavan,
                    2026-09-25) — it read "Use “…”". */}
                <CommandItem value={query} onSelect={() => choose(query.trim())}>
                  <span className="min-w-0 flex-1 truncate">{query.trim()}</span>
                  <span className="shrink-0 text-xs text-muted-foreground">{createLabel}</span>
                </CommandItem>
              </CommandGroup>
            )}
            {multiple && pickedNew.length > 0 && !query.trim() && (
              <CommandGroup>
                {pickedNew.map((o) => (
                  <CommandItem key={o} value={o} onSelect={() => toggle(o)}>
                    <Checkbox checked tabIndex={-1} aria-hidden className="pointer-events-none" />
                    <span className="flex-1 truncate">{o}</span>
                  </CommandItem>
                ))}
              </CommandGroup>
            )}
            {clearLabel && !multiple && !query.trim() && (
              <CommandGroup>
                <CommandItem value="__clear__" onSelect={() => choose("")}>
                  <span className="flex-1 truncate text-muted-foreground">{clearLabel}</span>
                  {!value && <Check className="size-4 shrink-0" />}
                </CommandItem>
              </CommandGroup>
            )}
            {matches.length > 0 && (
              <CommandGroup>
                {matches.map((o) => {
                  const used = o !== value && Boolean(taken?.includes(o));
                  return (
                    <CommandItem
                      key={o}
                      value={o}
                      disabled={used}
                      onSelect={() => !used && choose(o)}
                    >
                      {multiple && (
                        /* Already on another row: ticked and locked. */
                        <Checkbox
                          checked={used || picked.includes(o)}
                          tabIndex={-1}
                          aria-hidden
                          className="pointer-events-none"
                        />
                      )}
                      <span className="flex-1 truncate">{o}</span>
                      {!multiple && (used || o === value) && (
                        <Check className="size-4 shrink-0" />
                      )}
                    </CommandItem>
                  );
                })}
              </CommandGroup>
            )}
            <CommandEmpty>
              {creatable ? "Type a name to add it." : "No matches."}
            </CommandEmpty>
          </CommandList>
          {multiple && (
            <div className="flex items-center justify-between gap-2 border-t border-border p-1 pl-2.5">
              <span className="text-xs tabular-nums text-muted-foreground">
                {picked.length} selected
              </span>
              <Button
                size="sm"
                variant="ghost"
                disabled={picked.length === 0}
                onClick={() => {
                  multiple.onApply(picked);
                  setOpen(false);
                }}
              >
                Apply
              </Button>
            </div>
          )}
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export interface TableRowRemoveProps {
  /** Runs only after the tick. */
  onRemove: () => void;
  /** The SUBJECT — "Remove Gas Pr 1", or "Remove fee 2" while the row is blank. */
  "aria-label": string;
  disabled?: boolean;
  /**
   * `cell` (default): the pair FILLS its `relative p-0` td, ✕ over ✓ — the DS
   * Figma 28133:1526. `inline`: the pair sits side by side, for a bin that
   * lives inside another cell's padding (a charge's type cell).
   */
  layout?: "cell" | "inline";
}

/**
 * A ROW'S DELETE ASKS FIRST (Pavan, 2026-09-23). The bin, quiet until the row
 * is reached for, swaps on press for ✕ cancel and ✓ confirm — the tick is the
 * "are you sure?". Nothing goes on one careless click, and there is no dialog:
 * the question is asked where the finger already is. DS ui §10f "Rows".
 *
 * Escape, ✕, or focus leaving the pair takes it back. The row needs
 * `group/row` for the bin's hover reveal; the armed pair ignores hover and
 * stays until answered.
 */
export function TableRowRemove({
  onRemove,
  "aria-label": ariaLabel,
  disabled,
  layout = "cell",
}: TableRowRemoveProps) {
  const [armed, setArmed] = React.useState(false);
  const cancelRef = React.useRef<HTMLButtonElement>(null);
  React.useEffect(() => {
    if (armed) cancelRef.current?.focus();
  }, [armed]);

  if (!armed) {
    return (
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        aria-label={ariaLabel}
        disabled={disabled}
        className="text-muted-foreground opacity-0 transition-opacity group-hover/row:opacity-100 hover:bg-destructive/15 hover:text-destructive focus-visible:opacity-100 disabled:opacity-0"
        onClick={(e) => {
          e.stopPropagation();
          setArmed(true);
        }}
      >
        <Trash2 />
      </Button>
    );
  }

  const inline = layout === "inline";
  const btn =
    "flex items-center justify-center outline-none transition-colors focus-visible:relative focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50";
  return (
    <div
      role="group"
      aria-label={`${ariaLabel}?`}
      className={cn(
        "flex overflow-hidden",
        inline ? "h-7 gap-1" : "absolute inset-0 flex-col"
      )}
      onKeyDown={(e) => {
        if (e.key === "Escape") {
          e.stopPropagation();
          setArmed(false);
        }
      }}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setArmed(false);
      }}
    >
      <button
        ref={cancelRef}
        type="button"
        aria-label="Keep it"
        onClick={(e) => {
          e.stopPropagation();
          setArmed(false);
        }}
        className={cn(
          btn,
          "bg-fp-card-1 text-foreground hover:bg-accent",
          inline ? "size-7 rounded-sm" : "flex-1"
        )}
      >
        <X className="size-4" />
      </button>
      <button
        type="button"
        aria-label={`Yes, ${ariaLabel.charAt(0).toLowerCase()}${ariaLabel.slice(1)}`}
        onClick={(e) => {
          e.stopPropagation();
          setArmed(false);
          onRemove();
        }}
        className={cn(
          btn,
          "bg-destructive text-white hover:bg-destructive/90",
          inline ? "size-7 rounded-sm" : "flex-1"
        )}
      >
        <Check className="size-4" />
      </button>
    </div>
  );
}

import * as React from "react";

/* The shared state behind `form-steps.tsx`, kept apart so that file exports only components. */

/** True inside a stepped sheet's form. */
export const FormStepsContext = React.createContext(false);
/** True inside a step, so the sections in it do not become steps too. */
export const InsideFormStepContext = React.createContext(false);

/** The attributes that make an element a step the list can find. */
export function formStepAttrs(label: string) {
  return { "data-form-step": label };
}

/**
 * The classes a step's own element takes: room for the landing blink's fill,
 * pulled back out so the fields stay where they were.
 */
export const FORM_STEP_CLASS = "-m-3 rounded-lg p-3";

import * as React from "react";
import { CircleAlert, Info, Minus } from "lucide-react";
import { cn } from "@/lib/utils";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Steps, type StepItem } from "@/components/ui/steps";
import {
  FORM_STEP_CLASS,
  FormStepsContext,
  InsideFormStepContext,
  formStepAttrs,
} from "./form-steps-context";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

/* Shared building blocks for the Side Sheet variants (Figma 27610:58293). */

/** Section = muted group heading + fields. */
export function SheetSection({
  title,
  action,
  note,
  variant: variantProp = "card",
  flush = false,
  hanging,
  bodyClassName,
  headingClassName,
  children,
  className,
  id,
}: {
  title: string;
  /**
   * `card` — the default — draws the section as a bordered block with its
   * title in a tinted header band. A sheet is a stack of questions about
   * different things, and gaps alone were carrying the whole job of saying
   * where one subject ended and the next began; at 40px they did it only for
   * as long as nothing in a section grew. The border says it at any length.
   *
   * `plain` is the old heading-over-fields form, for the handful of places
   * that are a single continuous list rather than a set of groups.
   */
  variant?: "plain" | "card" | "outline";
  /**
   * Classes for the heading text — for a form that sets its group headings at
   * a different step of the type scale.
   */
  headingClassName?: string;
  /**
   * Card variant only: drop the body's padding so a single child can run edge
   * to edge under the header band.
   *
   * FOR A SECTION THAT IS ONE TABLE. A table already draws a border, a header
   * band and a rule between every row; set inside a padded card it became a
   * box in a box, with 16px of nothing between two lines doing the same job
   * and the table's own header band sitting a hair inside the card's. Flush,
   * the card's border IS the table's border and there is one edge instead of
   * two. The child owns its own insets — anything that is not the table (an
   * Add row, a footnote) has to bring its own padding and its own top rule.
   */
  flush?: boolean;
  /**
   * A control that HANGS OFF THE CARD'S BOTTOM-LEFT, outside it.
   *
   * FOR THE ADD ON A TABLE. The card's bottom-left corner squares so the two
   * join, and the control continues the table's last row rather than sitting
   * on a full-width band inside the card — a band draws a rule across the
   * whole card to carry one small act, and reads as an empty extra row of the
   * table. (Pavan, 2026-09-22.)
   */
  hanging?: React.ReactNode;
  /**
   * Classes for the BODY, not the card — for a section that has to fill the
   * height it is given rather than wrap its content. A composer's message box
   * is the case: it should run to the bottom of the sheet, and only the body
   * can be told to grow.
   */
  bodyClassName?: string;
  /**
   * Controls that act on the SECTION rather than on one field — "Add asset",
   * "Refresh". They sit on the heading row, right-aligned, because a control
   * that owns a whole section has no field to belong to.
   */
  action?: React.ReactNode;
  /** An explainer beside the heading — typically `SheetSectionNote`. */
  note?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
  /**
   * An anchor on the section, for a caller that has to bring one section into
   * view — a list's footer action that opens a record AT the part it is about.
   */
  id?: string;
}) {
  /* SECTION RHYTHM — 40 / 16. The gap between sections is 40px (owned by the
     sheet body); the gap between a section's title and its content is 16px. The
     outer gap being 2.5x the inner is what makes a heading read as belonging to
     the block beneath it rather than floating between two blocks. At 20 the
     title sat almost equidistant from both; below 16 it welds to the first
     field and the whole boundary rests on the 40.

     THE 16 IS MEASURED FROM THE TITLE, and that is the whole reason the heading
     row has no height of its own. It used to be `min-h-7` (28px) around a 20px
     line, and `items-center` split the spare 8px evenly — so what anyone could
     actually see between the words and the content was 20px, and 22px in a
     section whose heading also carried a 32px action button. The rule said 16
     and the screen said 20: the row was padding itself and calling it rhythm.

     An ACTION taller than the title now hangs off the line instead of pushing
     the content down: its wrapper is fixed at the title's own 20px and centres
     a taller child, which overflows the box without growing it. That holds for
     any control put there — a 32px button, a switch, a picker — so the 16
     cannot drift again the next time a section gains an action. */
  /* IN A STEPPED FORM (see `form-steps`) the card's band goes: a section
     that is fields becomes `plain`, a section that is a table keeps its rim as
     `outline`. A top-level section is also a step, named by its title. */
  const stepped = React.useContext(FormStepsContext);
  const insideStep = React.useContext(InsideFormStepContext);
  const isStep = stepped && !insideStep;
  const variant =
    stepped && variantProp === "card"
      ? flush || hanging
        ? "outline"
        : "plain"
      : variantProp;
  const stepAttrs = isStep ? formStepAttrs(title) : {};
  if (isStep) {
    children = (
      <InsideFormStepContext.Provider value>{children}</InsideFormStepContext.Provider>
    );
  }

  const heading = (
    <div className="flex items-center justify-between gap-4">
      <div className="flex items-center gap-1.5">
        <h3
          className={cn(
            "text-sm font-semibold text-muted-foreground",
            /* Sub-heading size, dimmed so the fields lead. */
            stepped && "text-base font-medium",
            headingClassName
          )}
        >
          {title}
        </h3>
        {/* Sits WITH the heading, not after the content: an explanation of
            how a section works belongs where the section is named, and on
            demand rather than as a paragraph everyone reads once. */}
        {note}
      </div>
      {action && (
        <div className="flex h-5 shrink-0 items-center justify-end">{action}</div>
      )}
    </div>
  );

  if (variant === "outline") {
    /* `outline` — the plain heading OVER an outlined box, no band. For a form
       whose group headings carry no fill but whose tables keep their rim.
       The box takes `flush` and `hanging` exactly as the card does. The rim
       is the data table's `--border`, per the DS table stroke. */
    const box = (
      <div
        className={cn(
          "flex shrink-0 flex-col overflow-hidden rounded-lg border border-border",
          !flush && "gap-4 p-4",
          hanging && "rounded-bl-none",
          bodyClassName
        )}
      >
        {children}
      </div>
    );
    return (
      <section
        id={id}
        {...stepAttrs}
        className={cn("flex shrink-0 flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
      >
        {heading}
        {hanging ? (
          <div className="flex flex-col">
            {box}
            <div className="flex w-full items-center justify-between gap-4">
              {hanging}
            </div>
          </div>
        ) : (
          box
        )}
      </section>
    );
  }

  if (variant === "card") {
    /* THE HEADING MOVES INTO A BAND, because a title inside a bordered block
       that shares the block's fill reads as the first row of content rather
       than as the name of what follows.

       The 16px title→content rhythm the plain variant measures so carefully is
       not needed here: the band's own edge is the separation, and it holds at
       any section length — which is the thing a 40px gap could not do. */
    const card = (
      <section
        id={hanging ? undefined : id}
        /* `shrink-0` IS LOAD-BEARING, not tidiness. The sheet body is a flex
           column, and `overflow-hidden` switches a flex item's automatic
           minimum size from its content to zero — so without this the whole
           card collapses to its own 2px of border. */
        className={cn(
          /* THE RIM IS `--fp-outline-1`, NOT `--border` (Pavan, 2026-09-22).
             The DS's stroke table has said so all along — outline-1 is "a
             card's own rim" and `--border` is "a structural divider" — and
             this card was drawing the divider weight round its outside, which
             is why a card sat heavier on the page than the lines inside it.
             In DARK the two tokens carry the same value, so this is a
             light-mode correction only. */
          "shrink-0 overflow-hidden rounded-lg border border-fp-outline-1",
          /* SQUARED WHERE THE HANGING CONTROL JOINS, so the two read as one
             shape rather than a rounded box with a tab floating under it. */
          hanging && "rounded-bl-none",
          /* THE CALLER'S CLASSES GO ON WHICHEVER ELEMENT IS THE OUTER ONE.
             With something hanging, that is the wrapper below, not this —
             `lg:col-span-3` landing here put the SECTION inside a grid item
             that was still one column wide, so a section could be told to take
             three columns and silently take one. (Found 2026-09-22, on the
             Documents table.) */
          !hanging && className
        )}
      >
        <div className="border-b border-border bg-fp-surface-1a px-4 py-2.5">
          {heading}
        </div>
        <div
          className={cn(
            "flex flex-col",
            !flush && "gap-4 p-4",
            bodyClassName
          )}
        >
          {children}
        </div>
      </section>
    );

    /* THE WRAPPER OWNS THE `shrink-0` AND THE ID once there is something
       hanging: the card and its tab are one block in the sheet's stack, and
       the body's 40px gap has to fall after the tab rather than between the
       two. */
    return hanging ? (
      <div id={id} className={cn("flex shrink-0 flex-col", className)}>
        {card}
        {/* THE HANGING ROW runs the card's width so a second thing can sit at
            its right end — the add on the left, a flag about the whole unit on
            the right. With one child `justify-between` leaves it on the left,
            which is where a lone add belongs. */}
        <div className="flex w-full items-center justify-between gap-4">
          {hanging}
        </div>
      </div>
    ) : (
      card
    );
  }

  return (
    <section
      id={id}
      {...stepAttrs}
      className={cn("flex flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
    >
      {heading}
      {children}
    </section>
  );
}

/**
 * The card's own insets, given back to one child of a `flush` section.
 *
 * A flush section is for a table, and a section is rarely ONLY a table — a
 * banner above it, a switch below. Those still need the 16px the body gave up,
 * and they need it individually rather than as a blanket, because the table
 * between them must keep running to the card's edge. Add `border-t`/`border-b`
 * at the call site where the inset meets the table: the rule belongs to the
 * boundary, and only the call site knows which side it is on.
 */
export function SheetSectionInset({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-4 p-4", className)}>{children}</div>
  );
}

/**
 * The remove control for an OPTIONAL section — the one that takes a section
 * that has been turned on back to its "Add …" box.
 *
 * A MINUS, NOT A BIN. A bin says a record is about to be destroyed, and this
 * destroys nothing: the section collapses to the CTA it came from and can be
 * added again in one click. The two icons look alike at 16px and mean opposite
 * things about whether the click can be taken back, so the optional-section
 * control never wears the bin — that stays on the ROW delete inside a table,
 * where a row really does go.
 *
 * QUIET UNTIL REACHED FOR. Emptying a section that was optional in the first
 * place should not compete with the table for attention, so it is a muted icon
 * that comes to full contrast and slides its label out on hover or focus. The
 * label is what makes it safe — a bare glyph beside a table of rows reads as
 * though it might remove a row.
 *
 * IT ASKS ONLY WHEN THERE IS SOMETHING TO LOSE. `hasContent` is the caller's
 * answer to "has anyone typed anything in here yet" — with rows filled the
 * click opens a confirm, and on an untouched section it just closes it. A
 * dialog over an empty table teaches people to dismiss dialogs without reading
 * them, which is exactly the habit that makes the one that matters useless.
 */
export function SheetSectionRemove({
  label,
  hasContent,
  onClick,
}: {
  /** Names what goes, e.g. "Remove peripherals". Shown on hover and to AT. */
  label: string;
  /**
   * True when the section holds something a person put there. Only then is
   * removal worth confirming — the caller knows what "filled in" means for its
   * own rows, so it decides rather than this component guessing.
   */
  hasContent?: boolean;
  onClick: () => void;
}) {
  const trigger = (
    <button
      type="button"
      onClick={hasContent ? undefined : onClick}
      aria-label={label}
      className="group/rm flex h-8 items-center gap-1.5 rounded-md px-2 text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
    >
      <Minus className="size-4 shrink-0" />
      <span className="max-w-0 overflow-hidden text-sm whitespace-nowrap opacity-0 transition-[max-width,opacity] duration-200 group-hover/rm:max-w-40 group-hover/rm:opacity-100 group-focus-visible/rm:max-w-40 group-focus-visible/rm:opacity-100">
        {label}
      </span>
    </button>
  );

  if (!hasContent) return trigger;

  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>{trigger}</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          {/* The button's own label, as a question — the dialog answers the
              click that opened it rather than restating the section's name. */}
          <AlertDialogTitle>{label}?</AlertDialogTitle>
          <AlertDialogDescription>
            Everything added here will be erased. This cannot be undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction variant="destructive" onClick={onClick}>
            Remove
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

/** Field = label + control + helper text. */
export function SheetField({
  label,
  description,
  required,
  children,
  className,
}: {
  /**
   * A node, not just a string: a field's label row sometimes carries a control
   * that acts on the whole field — an "Invite" beside a picker — and that
   * control belongs on the label row rather than trailing the field's body.
   */
  label?: React.ReactNode;
  description?: string;
  /** Marks the label with the destructive asterisk the DS forms already use. */
  required?: boolean;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {label && (
        <label className="block text-sm font-medium text-foreground">
          {label}
          {required && <span className="text-destructive"> *</span>}
        </label>
      )}
      {/* HELPER TEXT IS PART OF THE CONTROL, 4px under it — not the next thing
          down the form. At the field gap it floats between two controls and gets
          read as a label for the one below. Label→control keeps the field's own
          rhythm; control→helper is always 4px. */}
      <div className="flex flex-col gap-1">
        {children}
        {description && (
          <p className="text-xs text-muted-foreground">{description}</p>
        )}
      </div>
    </div>
  );
}

/** The top-of-body alert banner shared by every variant. */
export function InfoAlert() {
  return (
    <Alert>
      <CircleAlert />
      <AlertTitle>Alert Title</AlertTitle>
      <AlertDescription>This is an alert description.</AlertDescription>
    </Alert>
  );
}

/**
 * The "why does this section behave this way" explainer, on demand.
 *
 * A paragraph under a section is read once and then permanently in the way; the
 * rule it states is needed at the moment someone WONDERS, which is rarely the
 * moment they first arrive. On CLICK rather than hover, because hover cannot be
 * reached by touch and a tooltip that appears while you are aiming at something
 * else is worse than no tooltip.
 *
 * Deliberately NARROW. Explanations set to the full width of a sheet become one
 * long line that has to be tracked back across; a few short lines are read at a
 * glance.
 */
export function SheetSectionNote({
  label = "About this section",
  children,
}: {
  /** Names the button for assistive tech. */
  label?: string;
  children: React.ReactNode;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          className="flex size-5 items-center justify-center rounded-full text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 data-[state=open]:text-foreground"
        >
          <Info className="size-4" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 text-xs leading-relaxed">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/**
 * The sheet's step strip — the DS `Steps` control, sized and spaced for a
 * sheet header.
 *
 * A THIN WRAPPER ON PURPOSE. It exists so a sheet does not have to remember the
 * height and the border the header strip needs, not to be a second stepper: the
 * states, the numbering, the connector and the disabled-with-a-reason behaviour
 * are all `Steps`.
 */
export function SheetSteps({
  steps,
  value,
  onValueChange,
  tone,
  variant,
}: {
  steps: StepItem[];
  value: string;
  onValueChange: (next: string) => void;
  tone?: "brand" | "accent" | "neutral";
  variant?: "track" | "rings";
}) {
  return (
    <Steps
      tone={tone}
      variant={variant}
      steps={steps}
      value={value}
      onValueChange={onValueChange}
      className="my-2.5"
    />
  );
}

